)

func DecodeBase64(raw []byte) ([]byte, error) {
	// Handle empty string case explicitly
	if len(raw) == 0 {
		return []byte{}, nil
	}

	ret := make([]byte, base64.StdEncoding.DecodedLen(len(raw)))
	n, err := base64.StdEncoding.Decode(ret, raw)
